/**
 * Real 2×2 images, encoded by Pillow, as base64. Used to check that
 * `detectImageType` accepts real files and refuses cut-down ones.
 */
export const IMAGE_FIXTURES = {
  png:
    "iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAIAAAD91JpzAAAAFklEQVR4nGM8IRfFwMDAxMDAwMDAAAAPmAFE4knAJgAAAABJRU5ErkJggg==",
  jpeg:
    "",
  gif:
    "R0lGODdhAgACAIEAAMgeWgAAAAAAAAAAACwAAAAAAgACAAAIBgABCAQQEAA7",
  webp:
    "UklGRh4AAABXRUJQVlA4TBEAAAAvAUAAAAdQjyJXq/+BiOh/AAA=",
  webpLossy:
    "UklGRjIAAABXRUJQVlA4ICYAAABQAQCdASoCAAIAAoBCJaAABDOAAP7tj8f/+k2f/0mz/+k2fAAAAA==",
  avif:
    "",
} as const;

export function fixtureBytes(name: keyof typeof IMAGE_FIXTURES): Uint8Array {
  return new Uint8Array(Buffer.from(IMAGE_FIXTURES[name], "base64"));
}
